begin;
insert into public.organizations(name,code) values('Infirmary Pilot Organization','INF') on conflict(code) do update set name=excluded.name;
insert into public.facilities(organization_id,code,name,level,timezone) select id,'PILOT','Infirmary Pilot Facility','Infirmary','Asia/Manila' from public.organizations where code='INF' on conflict(organization_id,code) do update set name=excluded.name,level=excluded.level,timezone=excluded.timezone;
insert into public.departments(facility_id,code,name) select id,'REG','Registration' from public.facilities where code='PILOT' on conflict(facility_id,code) do update set name=excluded.name;
insert into public.roles(organization_id,name,description) select id,'Hospital Administrator','Full access for the first infirmary administrator.' from public.organizations where code='INF' on conflict(organization_id,name) do update set description=excluded.description;
insert into public.privileges(code,description,risk_level) values ('patients.read','View the master patient index','normal'),('patients.create','Register a patient','privileged'),('patients.update','Update patient demographics','privileged'),('audit.read','View audit events','high_risk') on conflict(code) do update set description=excluded.description,risk_level=excluded.risk_level;
insert into public.role_privileges(role_id,privilege_code) select r.id,p.code from public.roles r cross join public.privileges p join public.organizations o on o.id=r.organization_id where o.code='INF' and r.name='Hospital Administrator' on conflict do nothing;
create or replace function public.has_privilege(privilege text,target_facility uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.user_roles ur join public.profiles pr on pr.id=ur.user_id join public.role_privileges rp on rp.role_id=ur.role_id where ur.user_id=auth.uid() and ur.facility_id=target_facility and ur.active and pr.status='active' and rp.privilege_code=privilege)$$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$declare admin_role uuid;pilot_facility uuid;begin insert into public.profiles(id,full_name,employee_no) values(new.id,coalesce(nullif(new.raw_user_meta_data->>'full_name',''),split_part(coalesce(new.email,'User'),'@',1)),new.raw_user_meta_data->>'employee_no') on conflict(id) do nothing;if not exists(select 1 from public.user_roles) then select r.id into admin_role from public.roles r join public.organizations o on o.id=r.organization_id where o.code='INF' and r.name='Hospital Administrator';select f.id into pilot_facility from public.facilities f join public.organizations o on o.id=f.organization_id where o.code='INF' and f.code='PILOT';if admin_role is not null and pilot_facility is not null then insert into public.user_roles(user_id,role_id,facility_id) values(new.id,admin_role,pilot_facility) on conflict do nothing;end if;end if;return new;end$$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create sequence if not exists public.patient_mrn_seq;
create or replace function public.register_patient(target_facility uuid,first_name text,middle_name text,last_name text,birth_date date,sex_at_birth text,phone text,email text default null) returns uuid language plpgsql security definer set search_path='' as $$declare patient_id uuid;target_org uuid;generated_mrn text;begin if auth.uid() is null or not public.has_privilege('patients.create',target_facility) then raise exception 'Not authorized to register patients';end if;if nullif(trim(first_name),'') is null or nullif(trim(last_name),'') is null then raise exception 'First and last name are required';end if;select organization_id into target_org from public.facilities where id=target_facility and status='active';if target_org is null then raise exception 'Facility is unavailable';end if;generated_mrn:='INF-'||to_char(current_date,'YYYY')||'-'||lpad(nextval('public.patient_mrn_seq')::text,6,'0');insert into public.patients(organization_id,mrn,first_name,middle_name,last_name,birth_date,sex_at_birth,phone,email,created_by) values(target_org,generated_mrn,trim(first_name),nullif(trim(middle_name),''),trim(last_name),birth_date,nullif(trim(sex_at_birth),''),nullif(trim(phone),''),nullif(trim(email),''),auth.uid()) returning id into patient_id;insert into public.audit_events(organization_id,facility_id,actor_id,event_type,object_type,object_id,details) values(target_org,target_facility,auth.uid(),'patient.registered','patient',patient_id,jsonb_build_object('mrn',generated_mrn));return patient_id;end$$;
create or replace function public.update_patient(target_patient uuid,expected_version integer,new_first_name text,new_middle_name text,new_last_name text,new_birth_date date,new_sex_at_birth text,new_phone text,new_email text) returns integer language plpgsql security definer set search_path='' as $$declare target_facility uuid;target_org uuid;next_version integer;begin select p.organization_id,f.id into target_org,target_facility from public.patients p join public.facilities f on f.organization_id=p.organization_id where p.id=target_patient and public.has_privilege('patients.update',f.id) limit 1;if target_facility is null then raise exception 'Not authorized to update this patient';end if;update public.patients set first_name=trim(new_first_name),middle_name=nullif(trim(new_middle_name),''),last_name=trim(new_last_name),birth_date=new_birth_date,sex_at_birth=nullif(trim(new_sex_at_birth),''),phone=nullif(trim(new_phone),''),email=nullif(trim(new_email),''),updated_at=now(),version=version+1 where id=target_patient and version=expected_version returning version into next_version;if next_version is null then raise exception 'Patient was changed by another user. Refresh and try again';end if;insert into public.audit_events(organization_id,facility_id,actor_id,event_type,object_type,object_id,details) values(target_org,target_facility,auth.uid(),'patient.updated','patient',target_patient,jsonb_build_object('version',next_version));return next_version;end$$;
drop policy if exists "assigned patient read" on public.patients;create policy "privileged patient read" on public.patients for select using(exists(select 1 from public.facilities f where f.organization_id=patients.organization_id and public.has_privilege('patients.read',f.id)));
create policy "assigned roles read" on public.user_roles for select using(user_id=auth.uid());
create policy "scoped audit read" on public.audit_events for select using(facility_id is not null and public.has_privilege('audit.read',facility_id));
grant execute on function public.register_patient(uuid,text,text,text,date,text,text,text) to authenticated;grant execute on function public.update_patient(uuid,integer,text,text,text,date,text,text,text) to authenticated;grant execute on function public.has_privilege(text,uuid) to authenticated;
commit;
